import com.sun.net.httpserver.*;
import java.net.*; import java.io.*; import java.nio.file.*;
public class Stub {
  public static void main(String[] a) throws Exception {
    HttpServer s = HttpServer.create(new InetSocketAddress(9090), 0);
    s.setExecutor(java.util.concurrent.Executors.newCachedThreadPool());
    s.createContext("/", ex -> {
      String q = ex.getRequestURI().toString();
      try (FileWriter w = new FileWriter("/tmp/stub/log.txt", true)) { w.write(q + "\n"); }
      String mode = new String(Files.readAllBytes(Paths.get("/tmp/stub/mode.txt"))).trim();
      // mode: "STATUS|DELAYMS|BODY"
      String[] p = mode.split("\\|", 3);
      int st = Integer.parseInt(p[0]); long d = Long.parseLong(p[1]);
      try { Thread.sleep(d); } catch (Exception e) {}
      byte[] b = p[2].getBytes();
      ex.getResponseHeaders().add("Content-Type", "application/json");
      ex.sendResponseHeaders(st, b.length);
      ex.getResponseBody().write(b); ex.close();
    });
    s.start();
  }
}
EOF
